from fractions import Fraction as F
pct={'HR':8,'IT':15,'Acc':25,'Mkt':22,'Prod':30}
rat={'HR':(3,5),'IT':(2,3),'Acc':(3,7),'Mkt':(7,4),'Prod':(5,3)}
n={k:F(1600*v,100) for k,v in pct.items()}
fem=sum(n[k]*F(rat[k][1],sum(rat[k])) for k in n)
r=round(float(n['Prod']/fem*100),1)
opts={'A':64.3,'B':50.7,'C':44.9,'D':59.1}
assert r==opts['D']
for k in 'ABC': assert r!=opts[k]

